        "text": "Жінка віком 26 років звернулася повторно, бо симптоми почали заважати роботі та самообслуговуванню. Із анамнезу відомо, що подібного епізоду раніше не було, температура тіла нормальна. Під час бесіди уточнено динаміку симптомів, супутні хвороби та можливі провокуючі чинники; жоден із них не пояснює всю картину. Об’єктивно неврологічний статус дозволяє виділити провідний синдром: висхідна слабкість після інфекції, арефлексія і білково-клітинна дисоціація в лікворі. Лікар має обрати відповідь, яка найкраще пояснює синдром, локалізацію або подальшу тактику без зайвого розширення обстежень. Який діагноз найбільш імовірний?",
